const BULLISH_KEYWORDS = [
  'rally', 'breakout', 'surge', 'bull', 'ath', 'all-time high',
  'partnership', 'listing', 'upgrade', 'adoption', 'etf approval',
  'institutional', 'buy'
];
const BEARISH_KEYWORDS = [
  'hack', 'exploit', 'ban', 'lawsuit', 'sec', 'crash', 'dump',
  'bankrupt', 'fraud', 'rug', 'delisting', 'restrict'
];
const CRYPTO_SYMBOLS = [
  'BTC','ETH','BNB','SOL','ADA','XRP','DOT','MATIC','AVAX','LINK',
  'UNI','ATOM','LTC','NEAR','FTM','APT','ARB','OP','INJ','TIA'
];

const results = [];
const allItems = $input.all();

for (const item of allItems) {
  const articles = item.json.Data || item.json.news || item.json || [];
  const list = Array.isArray(articles) ? articles : [];

  for (const article of list.slice(0, 20)) {
    const text = ((article.title || '') + ' ' + (article.body || '') + ' ' + (article.headline || '')).toLowerCase();

    let sentiment = 0;
    for (const kw of BULLISH_KEYWORDS) { if (text.includes(kw)) sentiment += 0.1; }
    for (const kw of BEARISH_KEYWORDS) { if (text.includes(kw)) sentiment -= 0.15; }
    sentiment = Math.max(-1, Math.min(1, sentiment));

    const affectedSymbols = CRYPTO_SYMBOLS.filter(s => text.includes(s.toLowerCase()));

    if (Math.abs(sentiment) >= 0.2) {
      results.push({
        json: {
          source: article.source_info?.name || article.source || 'unknown',
          headline: article.title || article.headline || '',
          sentiment: Math.round(sentiment * 100) / 100,
          symbols: affectedSymbols,
          urgency: Math.abs(sentiment) >= 0.5 ? 'high' : 'normal',
          url: article.url || article.guid || '',
          published_at: article.published_on || article.publishedAt || new Date().toISOString()
        }
      });
    }
  }
}

return results.length > 0 ? results : [{ json: { skip: true } }];

const items = $input.all();
return items.map(item => ({
