    source: item.json.source,
    symbol: item.json.symbols && item.json.symbols.length > 0 ? item.json.symbols[0] + 'USDT' : null,
    headline: item.json.headline,
    sentiment: item.json.sentiment,
    urgency: item.json.urgency,
    raw_url: item.json.url
  }
}));
